    SELECT id INTO v_layout_id FROM ms_layout WHERE type = 'publication_detail' LIMIT 1;

    IF NOT EXISTS (SELECT 1 FROM content_detail_publications WHERE slug = 'peresmian-pabrik-baru-pt-daimler-commercial-vehicles-manufacturing-indonesia') THEN
