            content_id, title, slug, headline, description,
            is_publicated, thumbnail_path, publish_date, layout_id,
            is_slider, has_additional_image, has_additional_video,
            has_additional_file, has_additional_link, has_additional_text,
            created_at, updated_at
        ) VALUES (
            v_content_id,
            'Peresmian Pabrik Baru PT Daimler Commercial Vehicles Manufacturing Indonesia',
            'peresmian-pabrik-baru-pt-daimler-commercial-vehicles-manufacturing-indonesia',
            'Menteri Perindustrian Agus Gumiwang Kartasasmita memberikan sambutan dalam acara Peresmian Pabrik Baru PT Daimler Commercial Vehicles Manufacturing Indonesia (DCVMI), Cikarang, 10 Juni 2025.',
