    v_pub_id bigint;
    v_tag_id bigint;
BEGIN
    SELECT id INTO v_content_id FROM contents WHERE type = 'publication' LIMIT 1;
    SELECT id INTO v_layout_id FROM ms_layout WHERE type = 'publication_detail' LIMIT 1;

    IF NOT EXISTS (SELECT 1 FROM content_detail_publications WHERE slug = 'ekspor-lampaui-usd-273-juta-kemenperin-wujudkan-kemandirian-industri-alkes') THEN
