            VALUES ('App\\Models\\ContentDetailPublication', v_pub_id, v_tag_id, NOW(), NOW());
        END IF;

    END IF;
END $BODY$;

-- --------------------------------------------------------
-- Publication: Wamenperin Acungi Jempol Komitmen PT MMKI Penuhi TKDN
-- --------------------------------------------------------
DO $BODY$
DECLARE
    v_content_id bigint;
    v_layout_id bigint;
    v_pub_id bigint;
    v_tag_id bigint;
BEGIN
    SELECT id INTO v_content_id FROM contents WHERE type = 'publication' LIMIT 1;
    SELECT id INTO v_layout_id FROM ms_layout WHERE type = 'publication_detail' LIMIT 1;

    IF NOT EXISTS (SELECT 1 FROM content_detail_publications WHERE slug = 'wamenperin-acungi-jempol-komitmen-pt-mmki-penuhi-tkdn') THEN
        INSERT INTO content_detail_publications (
            content_id, title, slug, headline, description,
            is_publicated, thumbnail_path, publish_date, layout_id,
            is_slider, has_additional_image, has_additional_video,
            has_additional_file, has_additional_link, has_additional_text,
            created_at, updated_at
        ) VALUES (
            v_content_id,
            'Wamenperin Acungi Jempol Komitmen PT MMKI Penuhi TKDN',
            'wamenperin-acungi-jempol-komitmen-pt-mmki-penuhi-tkdn',
            'Wakil Menteri Perindustrian (Wamenperin) Faisol Riza mengapresiasi komitmen PT Mitsubishi Motors Krama Yudha (MMKI) dalam mematuhi regulasi Tingkat Komponen Dalam Negeri (TKDN). Pemenuhan TKDN dinilai...',
            '<p>Wakil Menteri Perindustrian (Wamenperin) Faisol Riza mengapresiasi komitmen PT Mitsubishi Motors Krama Yudha (MMKI) dalam mematuhi regulasi Tingkat Komponen Dalam Negeri (TKDN). Pemenuhan TKDN dinilai akan dapat memicu pertumbuhan industri komponen dalam negeri, sehingga memberikan kesempatan sektor industri kecil dan menengah (IKM) sebagai bagian dari rantai pasok distribusi.</p><p>“Pencapaian TKDN tidak hanya mendukung kemandirian industri otomotif, namun juga mendorong industri lain berkembang, termasuk IKM,” kata Wamenperin saat menghadiri perayaan produksi 1 juta unit PT MMKI, di Cikarang, Jawa Barat, Jumat (20/12).</p><p>Wamenperin mengatakan saat ini PT MMKI menjadi salah satu produsen kendaraan bermotor terbesar di Indonesia. Produksi 1 juta unit ini menunjukkan komitmen industri asal Jepang itu untuk berkomitmen dalam berinovasi, meningkatkan efisiensi dan produktivitas.</p><p>“Sehingga kita bisa lihat begitu besar kontribusinya pada industri otomotif dan ekonomi nasional. Apalagi komitmen terhadap pemenuhan TKDN yang hingga hari ini terus meningkat,” ujar Wamen Faisol.</p><p>Industri otomotif nasional secara umum mengalami peningkatan. Sepanjang 2023, industri kendaraan roda empat memproduksi total 1,39 juta unit dengan penjualan domestik lebih dari 1 juta unit dan ekspor mobil CBU mencapai 500 ribu unit, meningkat 6,7 persen dari 2022.</p><p>Sementara itu sejak Januari hingga November 2024, industri kendaraan roda empat nasional memproduksi total 1,09 juta unit, dengan 784 ribu unit merupakan penjualan wholesale, 428 ribu ekspor CBU, dan 42 ribu CKD. Adapun total penjualan komponen selama periode ini yakni 143 juta unit.</p><p>“PT MMKI telah menunjukkan komitmen kuat dalam mendukung industri nasional, dengan investasi Rp12,3 triliun dan menciptakan lebih dari 3.600 lapangan kerja,” kata Wamenperin.</p><p>President &amp; Chief Executive Officer Mitsubishi Motors, Takao Kato menyatakan, berkat dukungan dari pemerintah Indonesia, para pemasok, dan perusahaan mitra, pusat produksi Mitsubishi di Indonesia telah menjadi pilar utama bisnis perusahaan. “Kendaraan yang diproduksi di sini dijual di seluruh Indonesia, dan beberapa diekspor ke negara lain, termasuk negara-negara ASEAN, sehingga fasilitas ini memiliki peran penting sebagai lokasi produksi utama ASEAN. Kami akan terus meluncurkan produk-produk yang sangat menarik dan berkontribusi pada pengembangan ekonomi Indonesia lebih lanjut,” paparnya.</p><p>Pusat produksi yang berlokasi di Kawasan Industri GIIC di Kabupaten Bekasi, Jawa Barat tersebut merupakan perusahaan manufaktur bersama yang didirikan oleh Mitsubishi Motors, Mitsubishi Corporation, dan mitra lokal PT Krama Yudha. Pabrik ini mulai berproduksi pada April 2017 dengan kapasitas produksi tahunan sebesar 160.000 kendaraan. Pada tahun fiskal 2019, kapasitas produksi tersebut ditingkatkan menjadi 220.000 kendaraan, dan kendaraan yang diproduksi oleh perusahaan tersebut kini telah diekspor ke sekitar 50 negara.</p><p>“Pencapaian ini merupakan bukti penerimaan yang baik terhadap produk-produk MMKI di pasar domestik dan ekspor. MMKI akan selalu berkomitmen untuk menyediakan kendaraan berkualitas tinggi dan andal untuk memenuhi harapan dan permintaan pelanggan, sekaligus meningkatkan utilisasi fasilitas produksi. Selain itu, kami akan terus menambah jumlah negara tujuan ekspor,” ungkap Minoru Saito, Presiden Direktur MMKI.</p>',
            true,
            'img/berita/1736736392-3.JPG',
            '2024-12-21',
            v_layout_id,
            true,
            false,
            false,
            false,
            false,
            false,
            NOW(),
            NOW()
        ) RETURNING id INTO v_pub_id;
    ELSE
        SELECT id INTO v_pub_id FROM content_detail_publications WHERE slug = 'wamenperin-acungi-jempol-komitmen-pt-mmki-penuhi-tkdn' LIMIT 1;
    END IF;

    IF v_pub_id IS NOT NULL THEN
        INSERT INTO ms_tags (title, is_active, created_at, updated_at)
        SELECT 'Otomotif', true, NOW(), NOW()
        WHERE NOT EXISTS (SELECT 1 FROM ms_tags WHERE title = 'Otomotif');

        SELECT id INTO v_tag_id FROM ms_tags WHERE title = 'Otomotif' LIMIT 1;
        IF v_tag_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM content_tags
            WHERE content_type = 'App\\Models\\ContentDetailPublication'
              AND content_id = v_pub_id
              AND tag_id = v_tag_id
        ) THEN
            INSERT INTO content_tags (content_type, content_id, tag_id, created_at, updated_at)
            VALUES ('App\\Models\\ContentDetailPublication', v_pub_id, v_tag_id, NOW(), NOW());
        END IF;

    END IF;
END $BODY$;

-- --------------------------------------------------------
-- Publication: Wamenperin Ajak Huawei Berkontribusi dalam Transformasi Teknologi di RI
-- --------------------------------------------------------
DO $BODY$
DECLARE
    v_content_id bigint;
    v_layout_id bigint;
    v_pub_id bigint;
    v_tag_id bigint;
BEGIN
    SELECT id INTO v_content_id FROM contents WHERE type = 'publication' LIMIT 1;
    SELECT id INTO v_layout_id FROM ms_layout WHERE type = 'publication_detail' LIMIT 1;

    IF NOT EXISTS (SELECT 1 FROM content_detail_publications WHERE slug = 'wamenperin-ajak-huawei-berkontribusi-dalam-transformasi-teknologi-di-ri') THEN
        INSERT INTO content_detail_publications (
            content_id, title, slug, headline, description,
            is_publicated, thumbnail_path, publish_date, layout_id,
            is_slider, has_additional_image, has_additional_video,
            has_additional_file, has_additional_link, has_additional_text,
            created_at, updated_at
        ) VALUES (
            v_content_id,
            'Wamenperin Ajak Huawei Berkontribusi dalam Transformasi Teknologi di RI',
            'wamenperin-ajak-huawei-berkontribusi-dalam-transformasi-teknologi-di-ri',
            'Penerapan transformasi teknologi dan peningkatan kualitas sumber daya manusia (SDM) industri dapat mendukung tercapainya visi Indonesia Emas 2045. Upaya ini membutuhkan kontribusi besar dari berbagai ...',
            '<p>Penerapan transformasi teknologi dan peningkatan kualitas sumber daya manusia (SDM) industri dapat mendukung tercapainya visi Indonesia Emas 2045. Upaya ini membutuhkan kontribusi besar dari berbagai pihak, termasuk di antaranya sektor industri elektronik.</p>

<p>&ldquo;Kami mengapresiasi Huawei&nbsp;yang&nbsp;telah membawa bisnis dan teknologi canggih masuk ke Indonesia. Karena itu, kami mengajak industri ini untuk ikut berkontribusi dalam upaya peningkatan SDM industri dan transformasi teknologi di Indonesia,&rdquo; kata Wakil Menteri Perindustrian Faisol Riza dalam keterangan resminya di Jakarta, Jumat (20/12).</p>

<p>Beberapa waktu lalu, Wamenperin melakukan kunjungan kerja ke Kantor Pusat Huawei Innovation Center di Jakarta. &ldquo;Keterlibatan Huawei cukup penting untuk mendukung upaya kami dalam mengembangkan teknologi di Indonesia. Semoga ke depannya investasi dan bisnis Huawei di Indonesia berjalan baik,&rdquo; ujar Faisol.</p>

<p>Untuk mendukung terciptanya iklim usaha dan investasi yang kondusif di tanah air, Wamenperin berharap Huawei berperan aktif memberikan saran apabila menemui kendala terkait layanan pemerintah. &ldquo;Kami akan melakukan upaya-upaya untuk meningkatkan layanan yang berguna dalam mendukung iklim bisnis di Indonesia,&rdquo; tuturnya.</p>

<p>Wamenperin juga meminta kepada Huawei untuk terus meningkatkan Tingkat Komponen Dalam Negeri (TKDN) guna meningkatkan daya saing industri dalam negeri, serta mendongkrak pertumbuhan ekonomi nasional. &ldquo;Terkaithal ini,&nbsp;Huawei juga&nbsp;bisa&nbsp;mulai mempertimbangkan untuk melakukan beberapa hal, termasuk pengembangan teknologi dan membangun pabrik,&rdquo; imbuhnya.</p>

<p>CFO Huawei Indonesia, Jennifer Feng menyambut positif kunjungan Wamen Faisol ke Huawei Innovation Center. Dia berharap ke depannya dapat bekerja sama dengan pemerintah Indonesia. &ldquo;Ke depannya, kami berharap untuk dapat bekerja sama dengan PemerintahIndonesia untuk berkontribusi lebih banyak kepada bangsamendukung Indonesia dalam mencapai visi besar Indonesia Emas 2045,&rdquo; ungkap Jennifer.</p>',
            true,
            'img/berita/1736736536-3-2.JPG',
            '2024-12-20',
            v_layout_id,
            false,
            false,
            false,
            false,
            false,
            false,
            NOW(),
            NOW()
        ) RETURNING id INTO v_pub_id;
    ELSE
        SELECT id INTO v_pub_id FROM content_detail_publications WHERE slug = 'wamenperin-ajak-huawei-berkontribusi-dalam-transformasi-teknologi-di-ri' LIMIT 1;
    END IF;

    IF v_pub_id IS NOT NULL THEN
        INSERT INTO ms_tags (title, is_active, created_at, updated_at)
        SELECT 'Elektronika', true, NOW(), NOW()
        WHERE NOT EXISTS (SELECT 1 FROM ms_tags WHERE title = 'Elektronika');

        SELECT id INTO v_tag_id FROM ms_tags WHERE title = 'Elektronika' LIMIT 1;
        IF v_tag_id IS NOT NULL AND NOT EXISTS (
            SELECT 1 FROM content_tags
            WHERE content_type = 'App\\Models\\ContentDetailPublication'
              AND content_id = v_pub_id
              AND tag_id = v_tag_id
        ) THEN
            INSERT INTO content_tags (content_type, content_id, tag_id, created_at, updated_at)
            VALUES ('App\\Models\\ContentDetailPublication', v_pub_id, v_tag_id, NOW(), NOW());
        END IF;

    END IF;
END $BODY$;

-- --------------------------------------------------------
-- Publication: Tata Cara Pelaporan Survey Indeks Kepercayaan Industri (IKI) Tahun 2024
