    IF NOT EXISTS (SELECT 1 FROM content_detail_publications WHERE slug = 'lampaui-usd-4-miliar-ekspor-otomotif-nasional-dibidik-400-ribu-unit') THEN
        INSERT INTO content_detail_publications (
