-- Publication: 2019, Moody's Prediksi Industri Baja Bakal Tumbuh Stabil
-- --------------------------------------------------------
DO $BODY$
DECLARE
    v_content_id bigint;
    v_layout_id bigint;
    v_pub_id bigint;
    v_tag_id bigint;
BEGIN
    SELECT id INTO v_content_id FROM contents WHERE type = 'publication' LIMIT 1;
    SELECT id INTO v_layout_id FROM ms_layout WHERE type = 'publication_detail' LIMIT 1;

