            NOW()
        ) RETURNING id INTO v_pub_id;
    ELSE
        SELECT id INTO v_pub_id FROM content_detail_publications WHERE slug = 'krakatau-steel-waspadai-banjir-produk-baja-impor-di-tanah-air' LIMIT 1;
    END IF;

    IF v_pub_id IS NOT NULL THEN
    END IF;
END $BODY$;

